import { runScript } from '../../sdk/runner';

const target = process.argv[2] ?? 'man';
const durSec = Number(process.argv[3] ?? '60');
const styleSkill = process.argv[4] ?? 'Strength';

await runScript(async ({ bot, sdk }) => {
    // Equip best melee weapon
    const sword = sdk.findInventoryItem(/bronze sword/i);
    if (sword) await bot.equipItem(sword);
    const shield = sdk.findInventoryItem(/wooden shield/i);
    if (shield) await bot.equipItem(shield);

    // Set combat style
    const st0 = sdk.getState();
    const style = st0?.combatStyle?.styles.find(s => s.trainsSkills.includes(styleSkill));
    if (style) {
        await sdk.sendSetCombatStyle(style.index);
        await sdk.waitForTicks(1);
    }

    const pattern = new RegExp(target, 'i');
    const xp0: Record<string, number> = {};
    for (const s of sdk.getState()?.skills ?? []) xp0[s.name] = s.xp;
    const tick0 = sdk.getState()?.tick ?? 0;
    const t0 = Date.now();
    let attacks = 0;

    while (Date.now() - t0 < durSec * 1000) {
        const npc = sdk.findNearbyNpc(pattern, { reachable: true } as any);
        if (!npc) {
            await sdk.waitForTicks(2);
            continue;
        }
        try {
            const r = await bot.attack(npc, 4000);
            attacks++;
            if (!r.success) { await sdk.waitForTicks(1); continue; }
            // wait for combat to end (kill or deaggro)
            await sdk.waitForCondition(s => !s.player?.combat?.inCombat, 15000).catch(() => {});
        } catch (e) {
            await sdk.waitForTicks(1);
        }
    }

    const st = sdk.getState();
    const xpNow: Record<string, number> = {};
    for (const s of st?.skills ?? []) xpNow[s.name] = s.xp;
    const gained: Record<string, number> = {};
    for (const k of Object.keys(xpNow)) {
        const d = xpNow[k] - (xp0[k] ?? 0);
        if (d) gained[k] = d;
    }
    return {
        target,
        seconds: Math.round((Date.now() - t0) / 1000),
        ticks: (st?.tick ?? 0) - tick0,
        attacks,
        gainedXp: gained,
        totalDamage: (gained['Attack'] ?? 0) / 4 + (gained['Strength'] ?? 0) / 4 + (gained['Defence'] ?? 0) / 4 + (gained['Hitpoints'] ?? 0) / (4 / 1.33),
        hp: st?.player?.hp,
        pos: [st?.player?.worldX, st?.player?.worldZ],
        levels: Object.fromEntries((st?.skills ?? []).filter(s => ['Attack', 'Strength', 'Defence', 'Hitpoints'].includes(s.name)).map(s => [s.name, s.baseLevel])),
    };
}, { timeout: (durSec + 30) * 1000, printState: false });

